/**
 * Initialize the filter controls.
 *
 * @param {integer} uniqueid
 * @param {array} selectedfilters
 */
export const filters = (uniqueid, selectedfilters = [], pendingdenied = false) => {

    // Ensure localised strings are initialised before any preselected
    // pending filter permission checks run (e.g. URL pending=1).
    loadStrings();

    $filtersbox = $('#' + uniqueid);
    var $channelsControl = $filtersbox.find('.filtercontrol[data-key="channels"]');
    var $selectAllChannels = $channelsControl.find('.vitrinadb-channels-selectall');
    var $pendingcontrol = $filtersbox.find('.filterpending input[name="pending"]');
    var arrPrechecked = [];
    var hasArrPrechecked = false;

    // Tri-state selector for the channels "select all" checkbox.
    // 'all'    -> every channel selected;
    // 'none'   -> no channel selected (backend returns no resources);
    // 'single' -> "single-node" mode: channel checkboxes are hidden and
    //             clicking any node selects only that node (whole subtree);
    //             queries triggered outside the tree (fulltext/sort/...)
    //             run against ALL channels.
    var selectAllState = 'all';
    // Current selected node (full path value) when in 'single' mode.
    var singleNodeValue = null;
    // Whether the last filter change was triggered by clicking a tree node.
    var lastNodeTrigger = false;

    // Sync the "select all" checkbox visual state according to the current
    // tri-state mode. Pure UI: it never triggers searches nor restores the
    // pending permissions (that is done by applyPendingChannelPermissions).
    var refreshSelectAllUI = function() {
        if (!$selectAllChannels.length) {
            return;
        }

        // Drive the visual state through a dedicated data-state attribute so we
        // never rely on the native :checked / :indeterminate pseudo-classes
        // (which Boost Union and some browsers render unreliably).
        if (selectAllState === 'single') {
            $channelsControl.addClass('vitrina-single-mode');
            $selectAllChannels.attr('data-state', 'single');
            $selectAllChannels.prop('indeterminate', false);
            $selectAllChannels.prop('checked', false);
        } else {
            $channelsControl.removeClass('vitrina-single-mode');
            $selectAllChannels.prop('indeterminate', false);
            if (selectAllState === 'all') {
                $selectAllChannels.prop('checked', true);
                $selectAllChannels.attr('data-state', 'all');
            } else {
                $selectAllChannels.prop('checked', false);
                $selectAllChannels.attr('data-state', 'none');
            }
        }
    };

    // Whether the pending-approval permission currently disables channel
    // selection.
    var applyPendingDisabled = false;

    var updateTreeExpansion = function() {
        return;
    };

    var normalizeChannelPath = function(value) {
        return String(value || '').replace(/\u00a0/g, ' ').trim();
    };

    var getPendingPermissionMessage = function() {
        var raw = String(s.pendingpermissionnotset || '').trim();
        if (raw === '' || raw === 'pendingpermissionnotset') {
            return '尚未为您的账户设置审批指定类别的权限，如需开通请联系管理人员';
        }
        return raw;
    };

    var getChannelPathValue = function($checkbox) {
        var value = normalizeChannelPath($checkbox.val());
        if (value !== '') {
            return value;
        }

        var $label = $checkbox.closest('.filter-option').find('> label');
        var title = normalizeChannelPath($label.attr('title'));
        if (title !== '') {
            return title;
        }

        return normalizeChannelPath($label.text());
    };

    var setSelectAllDisabled = function(disabled) {
        if ($selectAllChannels.length) {
            $selectAllChannels.prop('disabled', disabled);
        }
    };

    var applyPendingChannelPermissions = function() {
        if (!$pendingcontrol.length || !$channelsControl.length) {
            return true;
        }

        var $allChannelCheckboxes = $channelsControl.find('input.filteroption');

        if (!$pendingcontrol.is(':checked')) {
            if (hasArrPrechecked) {
                $allChannelCheckboxes.each(function(index) {
                    $(this).prop('checked', !!arrPrechecked[index]);
                });
                hasArrPrechecked = false;
                arrPrechecked = [];
            }

            $allChannelCheckboxes.prop('disabled', false);
            setSelectAllDisabled(false);
            applyPendingDisabled = false;
            // Leaving the pending-approval filter: drop the restricted scope
            // and the node highlighting that were injected while checked.
            if (gPendingAllowedChannels.length > 0 || gSingleNodeValues.length > 0) {
                gPendingAllowedChannels = [];
                gSingleNodeValues = [];
            }
            if ($channelsControl.length) {
                $channelsControl.find('.filter-option').removeClass('vitrina-node-selected vitrina-node-ancestor vitrina-node-permitted');
            }
            updateTreeExpansion();
            refreshSelectAllUI();
            return true;
        }

        var permissionTitle = normalizeChannelPath($pendingcontrol.attr('title'));
        if (permissionTitle === '') {
            showPendingPermissionNotice();
            $pendingcontrol.prop('checked', false);
            return false;
        }

        if (!hasArrPrechecked) {
            arrPrechecked = [];
            $allChannelCheckboxes.each(function() {
                arrPrechecked.push($(this).is(':checked'));
            });
            hasArrPrechecked = true;
        }

        if (permissionTitle === '*') {
            $allChannelCheckboxes.prop('disabled', false);
            setSelectAllDisabled(false);
            applyPendingDisabled = false;
            $allChannelCheckboxes.prop('checked', true);
            // Permission covers all channels: keep the query global (no
            // concrete channels filter) and clear any node highlight.
            gPendingAllowedChannels = [];
            gSingleNodeValues = [];
            if ($channelsControl.length) {
                $channelsControl.find('.filter-option').removeClass('vitrina-node-selected vitrina-node-ancestor vitrina-node-permitted');
            }
            updateTreeExpansion();
            refreshSelectAllUI();
            return true;
        }

        var allowedPaths = {};
        permissionTitle.split(/\r?\n/).forEach(path => {
            var normalized = normalizeChannelPath(path);
            if (normalized !== '') {
                allowedPaths[normalized] = true;
            }
        });

        if (Object.keys(allowedPaths).length === 0) {
            showPendingPermissionNotice();
            $pendingcontrol.prop('checked', false);
            return false;
        }

        $allChannelCheckboxes.each(function() {
            var $checkbox = $(this);
            var channelpath = getChannelPathValue($checkbox);
            var isallowed = !!allowedPaths[channelpath];

            $checkbox.prop('checked', isallowed);
            $checkbox.prop('disabled', !isallowed);
        });

        setSelectAllDisabled(true);
        applyPendingDisabled = true;
        if (selectAllState === 'single') {
            // In single-node mode, keep only the allowed nodes clickable.
            $allChannelCheckboxes.off('click.vitrinasingle');
            $allChannelCheckboxes.each(function() {
                var $checkbox = $(this);
                var channelpath = getChannelPathValue($checkbox);
                var isallowed = !!allowedPaths[channelpath];
                $checkbox.prop('disabled', !isallowed);
            });

            // Restricted pending-approval permission: override the active scope
            // with the permitted channels so the query stays channel-scoped and
            // cannot broaden to unapproved categories (fixes over-permission).
            // Keep a permanent subtle highlight on every permitted node so the
            // user can always see them; a manually clicked node additionally
            // carries .vitrina-node-selected.
            gPendingAllowedChannels = Object.keys(allowedPaths);
            gSingleNodeValues = gPendingAllowedChannels.slice();
            $channelsControl.find('.filter-option').removeClass('vitrina-node-permitted');
            $allChannelCheckboxes.each(function() {
                var $checkbox = $(this);
                var channelpath = getChannelPathValue($checkbox);
                if (!!allowedPaths[channelpath]) {
                    $checkbox.closest('.filter-option').addClass('vitrina-node-permitted');
                }
            });
        }
        updateTreeExpansion();
        refreshSelectAllUI();
        return true;
    };

    var applyFilters = function(fromNode) {

        // A node-external trigger while in single-node mode: drop the active
        // single-node scope and search across ALL channels (as if every
        // category were selected), and clear the node highlight.
        if (gChannelsSelectAllState === 'single' && !fromNode) {
            if (gPendingAllowedChannels.length === 0) {
                // No restricted pending-approval scope: drop the active
                // single-node scope and search across ALL channels (as if
                // every category were selected), clearing the node highlight.
                gSingleNodeValues = [];
                if ($channelsControl.length) {
                    $channelsControl.find('.filter-option').removeClass('vitrina-node-selected vitrina-node-ancestor vitrina-node-permitted');
                }
            }
            // Otherwise the pending-approval permission restricts the query to
            // the permitted channels (gSingleNodeValues already holds them);
            // keep that scope and the node highlighting intact.
        }

        if (!loading) {
            restartSearch(uniqueid);
            loadCourses(uniqueid, $filtersbox.find('.block_vitrina-tabcontent.active'), true);
        }
    };

    selectedfilters.forEach(filter => {

        if (filter.key === 'fulltext') {
            $filtersbox.find('.filterfulltext input[name="q"]').val(filter.values.join(' '));
            return;
        }

        if (filter.key === 'author') {
            if (filter.values && filter.values.length > 0) {
                var authorValue = String(filter.values[0]);
                gUrlAuthorFilter = authorValue;
                var $authorselect = $filtersbox.find('.filterauthor select[name="author"]');
                if ($authorselect.length > 0) {
                    // Just pre-select the value from the URL. The author has no
                    // records fallback is handled where the query result is
                    // actually known to be empty (see loadCourses done).
                    $authorselect.val(authorValue);
                }
            }
            return;
        }

        if (filter.key === 'pending') {
            if (filter.values && filter.values.length > 0) {
                var pendingValue = String(filter.values[0]);
                if (pendingValue !== '' && pendingValue !== '0') {
                    // Check the "Only pending approval records" checkbox.
                    $filtersbox.find('.filterpending input[name="pending"]').prop('checked', true);
                }
            }
            return;
        }

        $filtersbox.find('.filtercontrol[data-key="' + filter.key + '"] .filteroptions').each(function() {
            var $filteroptions = $(this);

            filter.values.forEach(value => {
                $filteroptions.find('input[value="' + value + '"]').prop('checked', true);
            });
        });
    });

    $filtersbox.find('.filtercontrol .filteroptions input').on('change', function() { applyFilters(); });
    $filtersbox.find('.filtersort select[name="sort"]').on('change', function() { applyFilters(); });
    $filtersbox.find('.filtersortdirection select[name="sortdirection"]').on('change', function() { applyFilters(); });
    $filtersbox.find('.filterauthor select[name="author"]').on('change', function() { applyFilters(); });
    $filtersbox.find('.filtertags select[name="tagsfilter"]').on('change', function() { applyFilters(); });

    $filtersbox.find('.filterfulltext button').on('click', function() { applyFilters(); });
    $filtersbox.find('.filterfulltext input').on('keypress', function(e) {
        if (e.which == 13) {
            applyFilters();
        }
    });

    $filtersbox.find('.vitrina-filter-responsivebutton').on('click', function() {
        $filtersbox.addClass('opened-popup');
    });

    $filtersbox.find('.vitrina-filter-closebutton').on('click', function() {
        $filtersbox.removeClass('opened-popup');
    });

    // Initialize the channels filter as a collapsible tree when there are
    // parent channels with children. A channel value whose label starts
    // with "--" is treated as a child of the previous non-prefixed
    // channel in the list (built server-side).
    if ($channelsControl.length) {

        updateTreeExpansion = function() {
            $channelsControl.find('.filter-optiongroup.haschilds').each(function() {
                var $group = $(this);

                var hasSelectedDescendant = $group.find('ul.filteroptions input.filteroption:checked').length > 0;
                var isSelectedSelf = $group.find('> .filter-option > input.filteroption:checked').length > 0;
                var $icon = $group.find('> .filter-option .tree-toggle');

                if (hasSelectedDescendant || isSelectedSelf) {
                    $group.addClass('expanded');
                    $icon.removeClass('fa-plus-circle').addClass('fa-minus-circle');
                }
            });
        };

        // Initial expansion based on any preselected channels.
        updateTreeExpansion();

        // Initial sync for the select-all checkbox. The URL parameter
        // "single=1" makes the catalog page boot directly into single-node
        // mode (checkbox shows the dash, node checkboxes hidden).
        var urlParams = new URLSearchParams(window.location.search);
        if (urlParams.get('single') === '1') {
            selectAllState = 'single';
            gChannelsSelectAllState = 'single';
            gSingleNodeValues = [];
            $channelsControl.find('input.filteroption').prop('checked', false);
        } else {
            selectAllState = 'all';
            gChannelsSelectAllState = 'all';
        }
        refreshSelectAllUI();

        // In "single-node" mode a node is treated as an exact single node: only the
        // clicked node's own channel value is used (the backend matches it
        // within the "##value##" separators, so child nodes are not included).
        var collectSubtreeValues = function(target) {
            var normalized = normalizeChannelPath(target);
            if (normalized === '') {
                return [];
            }
            return [target];
        };

        // When a node is clicked in "single-node" mode, select that exact single
        // node, highlight it and its ancestors, and trigger a node-scoped
        // search.
        if ($selectAllChannels.length) {
            $channelsControl.on('click', '.filter-option label', function(e) {
                if (selectAllState !== 'single') {
                    return;
                }
                // Prevent the native label->checkbox toggling: in single-node
                // mode we drive the selection entirely from here.
                e.preventDefault();
                e.stopPropagation();

                var $label = $(this);
                var $option = $label.closest('.filter-option');
                var $checkbox = $option.find('.filteroption').first();
                if (!$checkbox.length || $checkbox.prop('disabled')) {
                    return;
                }

                var channelpath = getChannelPathValue($checkbox);
                if (channelpath === '') {
                    return;
                }

                // Highlight the selected node and all its ancestors.
                $channelsControl.find('.filter-option').removeClass('vitrina-node-selected');
                $option.addClass('vitrina-node-selected');
                $option.parents('.filter-optiongroup').addClass('vitrina-node-ancestor');

                // Store the exact single node as the active scope (no child nodes).
                gSingleNodeValues = collectSubtreeValues(channelpath);
                gChannelsSelectAllState = 'single';

                // Expand the tree towards the selected node if collapsed.
                $option.parents('.filter-optiongroup.haschilds').addClass('expanded');
                var $icon = $option.parents('.filter-optiongroup.haschilds').find('> .filter-option .tree-toggle');
                $icon.removeClass('fa-plus-circle').addClass('fa-minus-circle');

                applyFilters(true);
            });
        }

        // Toggle all channels. Because the "select all" checkbox supports a
        // third (indeterminate) state, we drive the cycle with click events:
        // 'all' -> 'none' -> 'single' -> 'all'.
        if ($selectAllChannels.length) {
            $selectAllChannels.on('click', function(e) {
                e.preventDefault();

                var next;
                if (selectAllState === 'all') {
                    next = 'none';
                } else if (selectAllState === 'none') {
                    next = 'single';
                } else {
                    next = 'all';
                }

                selectAllState = next;
                gChannelsSelectAllState = next;

                if (next === 'single') {
                    // Enter single-node mode: clear any previous node scope.
                    gSingleNodeValues = [];
                } else {
                    gSingleNodeValues = [];

                    // In 'all' and 'none' the select-all checkbox also drives
                    // the underlying node checkboxes (historical behaviour).
                    var $allChannelCheckboxes = $channelsControl.find('input.filteroption');
                    $allChannelCheckboxes.prop('checked', (next === 'all'));
                }

                // Remove node highlighting when leaving single-node mode.
                if (next !== 'single') {
                    $channelsControl.find('.filter-option').removeClass('vitrina-node-selected vitrina-node-ancestor vitrina-node-permitted');
                }

                refreshSelectAllUI();
                applyFilters();
            });
        }

        // Toggle expand/collapse when clicking on the parent icon.
        $channelsControl.on('click', '.tree-toggle', function(e) {
            e.preventDefault();
            e.stopPropagation();

            var $group = $(this).closest('.filter-optiongroup.haschilds');
            $group.toggleClass('expanded');

            var $icon = $group.find('> .filter-option .tree-toggle');
            if ($group.hasClass('expanded')) {
                $icon.removeClass('fa-plus-circle').addClass('fa-minus-circle');
            } else {
                $icon.removeClass('fa-minus-circle').addClass('fa-plus-circle');
            }
        });

        // Keep expansion state in sync with checkbox changes. In single-node mode
        // the generic change handler is not used (nodes are handled by the
        // label click binding), but we still refresh the select-all UI.
        $channelsControl.on('change', 'input.filteroption', function() {
            updateTreeExpansion();
            if (selectAllState === 'single') {
                return;
            }
            var $allChannelCheckboxes = $channelsControl.find('input.filteroption');
            if ($allChannelCheckboxes.length === 0) {
                selectAllState = 'none';
            } else {
                selectAllState = ($allChannelCheckboxes.filter(':checked').length === $allChannelCheckboxes.length)
                    ? 'all' : 'none';
            }
            refreshSelectAllUI();
        });
    }

    if ($pendingcontrol.length) {
        $pendingcontrol.on('change', function() {
            if (!applyPendingChannelPermissions()) {
                return;
            }
            applyFilters();
        });

        if ($pendingcontrol.is(':checked')) {
            applyPendingChannelPermissions();
        }
    }

    // The visitor opened the catalog with pending=1 but has no pending-approval
    // permission (checkbox is hidden): tell them with a centred modal.
    if (pendingdenied) {
        showPendingPermissionNotice();
    }

};